                String m = String.valueOf(e.getMessage());
                check(!m.contains(AT), "echoed access token redacted from refresh failure");
                check(!m.contains(RID), "echoed refresh id redacted from refresh failure");
                check(e.referenceToken() == null || !e.referenceToken().contains(RID),
                        "echoed refresh id redacted from referenceToken");
            }
            tm.close();
            for (String line : log) {
                check(line == null || !(line.contains(PASS) || line.contains(AT) || line.contains(RID)),
                        "no secret in any log line end-to-end");
            }
        } finally {
            server.stop(0);
        }
        System.out.println("probe: all " + checks + " checks passed");
    }
}
